Original:
```typescript
export function cardFee(amountCents: number, percentBp = 290, minimumCents = 30): number {
  if (amountCents < 0) {
    throw new RangeError(`amount cannot be negative, got ${amountCents}`);
  }
  const fee = Math.round((amountCents * percentBp) / 10000);
  if (fee < 20) {
    return minimumCents;
  }
  return fee;
}

```

